public java.util.List<BigDecimal> splitEvenly(BigDecimal total, int parts) {
    if (parts <= 0) throw new IllegalArgumentException("parts must be positive");
    long cents = total.movePointRight(2).longValueExact();
    java.util.List<BigDecimal> shares = new java.util.ArrayList<>();
    for (int i = 0; i < parts; i++) {
        long c = cents / parts + (i < cents % parts ? 1 : 0);
        shares.add(BigDecimal.valueOf(c, 2));
    }
    return shares;
}

